code.C:
#include <stdio.h>
int main() {
    char s[1005], ch[10];
    if (scanf("%s %s", s, ch) != 2) return 0;
    char odds[1005], evens[1005];
    int o = 0, e = 0;
    for (int i = 0; s[i]; i++) {
        if ((s[i] - '0') % 2 != 0) odds[o++] = s[i];
        else evens[e++] = s[i];
    }
    odds[o] = '\0'; evens[e] = '\0';
    if (ch[0] == '0') printf("%s%s\n", odds, evens);
    else printf("%s%s\n", evens, odds);
    return 0;
}

