code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s = sc.next(), ch = sc.next();
            StringBuilder odds = new StringBuilder(), evens = new StringBuilder();
            for (char c : s.toCharArray()) {
                if ((c - '0') % 2 != 0) odds.append(c);
                else evens.append(c);
            }
            if (ch.equals("0")) System.out.println(odds.toString() + evens.toString());
            else System.out.println(evens.toString() + odds.toString());
        }
    }
}

