        const s = toks[0], ch = toks[1];
        const odds = s.split("").filter(c => parseInt(c, 10) % 2 !== 0).join("");
        const evens = s.split("").filter(c => parseInt(c, 10) % 2 === 0).join("");
        if (ch === "0") console.log(odds + evens);
        else console.log(evens + odds);
    }
}
